// controllers/pdfController.ts
import jsPDF from 'jspdf';
import autoTable from 'jspdf-autotable';

// 🔥 PEGA AQUÍ EL CÓDIGO BASE64 DE TU LOGO (La cadena larga que empieza con "data:image/png;base64...")
const LOGO_BASE64 = "data:image/png;base64,"
// --- 1. GENERAR FACTURA ---
export function generarPdfFactura(factura: any, items: any[]) {
  const doc = new jsPDF();
  
  // Colores de AgroLactec
  const colorAzul: [number, number, number] = [2, 132, 199];
  const colorTexto: [number, number, number] = [51, 51, 51]; // Gris oscuro

  // 1. Cabecera (Fondo azul)
  doc.setFillColor(colorAzul[0], colorAzul[1], colorAzul[2]);
  doc.rect(0, 0, 210, 40, 'F');

  // 2. "Chip" blanco para el logo (para que resalte y no se vea el recuadro del PNG)
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(10, 5, 34, 30, 4, 4, 'F'); 

  // 3. Agregar el logo
  try {
    doc.addImage(LOGO_BASE64, 'PNG', 13, 8, 28, 24); 
  } catch (e) {
    console.warn("No se pudo cargar el logo en la factura");
  }

  // 4. Texto Izquierdo (AHORA EN NEGRO)
  doc.setTextColor(51, 51, 51); // Cambiamos de blanco a oscuro
  doc.setFontSize(15);
  doc.text('AGROLACTEC S.A. DE C.V.', 50, 18); // Movido a la derecha por el chip
  doc.setFontSize(10);
  doc.text('Distribuidora de Lácteos y Embutidos', 50, 26);
  
  // 5. Datos de la factura (Derecha - Blanco)
  doc.setTextColor(255, 255, 255);
  const xDerecha = 196; 
  doc.setFontSize(14);
  const tipoComprobante = factura.tipo_comprobante.replace(/_/g, ' ');
  doc.text(tipoComprobante, xDerecha, 18, { align: 'right' }); 
  doc.setFontSize(9);
  doc.text(`N°: ${factura.correlativo}`, xDerecha, 26, { align: 'right' });
  doc.text(`Fecha: ${new Date(factura.fecha_emision).toLocaleDateString()}`, xDerecha, 32, { align: 'right' });

  // Datos del cliente
  doc.setTextColor(colorTexto[0], colorTexto[1], colorTexto[2]);
  doc.setFontSize(10);
  doc.text('CLIENTE:', 14, 55);
  doc.setFont('helvetica', 'bold');
  doc.text(factura.cliente_nombre, 14, 61);
  doc.setFont('helvetica', 'normal');
  
  doc.text('CONDICIÓN DE PAGO:', 130, 55);
  doc.text(factura.condicion_pago.replace(/_/g, ' '), 130, 61);

  // Tabla de Productos
  const body = items.map(item => {
    const nombre = item.nombre_producto || item.productos?.nombre || 'Producto sin nombre';
    const cantidad = item.cantidad || 0;
    const precio = Number(item.precio_aplicado || item.precio_unitario || 0);
    const subtotal = Number(item.subtotal || item.subtotal_item || (precio * cantidad) || 0);

    return [ nombre, `${cantidad} ${item.unidad_medida || 'UND'}`, `$${precio.toFixed(2)}`, `$${subtotal.toFixed(2)}` ];
  });

  autoTable(doc, {
    startY: 70,
    head: [['Descripción', 'Cant.', 'Precio Unit.', 'Total']],
    body: body,
    theme: 'grid',
    headStyles: { fillColor: colorAzul, textColor: 255 },
    styles: { fontSize: 9 }
  });

  // Totales
  const finalY = (doc as any).lastAutoTable.finalY + 10;
  doc.setFontSize(10);
  doc.text(`Subtotal: $${Number(factura.subtotal).toFixed(2)}`, 140, finalY);
  doc.text(`IVA (13%): $${Number(factura.impuesto_iva).toFixed(2)}`, 140, finalY + 6);
  
  doc.setFontSize(14);
  doc.setFont('helvetica', 'bold');
  doc.text(`TOTAL: $${Number(factura.total).toFixed(2)}`, 140, finalY + 16);

  // Firmas
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  doc.line(20, finalY + 50, 80, finalY + 50);
  doc.text('Firma Autorizada', 35, finalY + 55);
  doc.line(130, finalY + 50, 190, finalY + 50);
  doc.text('Recibido por Cliente', 145, finalY + 55);

  doc.save(`Factura_${factura.correlativo}.pdf`);
}

// --- 2. GENERAR PICKING LIST ---
export function generarPdfPickingList(orden: any, pickingList: any[]) {
  const doc = new jsPDF();
  const colorNaranja: [number, number, number] = [245, 158, 11];

  // 1. Cabecera (Fondo naranja)
  doc.setFillColor(colorNaranja[0], colorNaranja[1], colorNaranja[2]);
  doc.rect(0, 0, 210, 40, 'F');
  
  // 2. "Chip" blanco para el logo
  doc.setFillColor(255, 255, 255);
  doc.roundedRect(10, 5, 34, 30, 4, 4, 'F'); 

  // 3. Agregar el logo
  try {
    doc.addImage(LOGO_BASE64, 'PNG', 13, 8, 28, 24); 
  } catch (e) {
    console.warn("No se pudo cargar el logo en el picking list");
  }

  // 4. Texto Izquierdo (AHORA EN NEGRO)
  doc.setTextColor(51, 51, 51); 
  doc.setFontSize(18);
  doc.text('ORDEN DE DESPACHO', 50, 18); 
  doc.setFontSize(10);
  doc.text('AgroLactec S.A. de C.V.', 50, 26);
  
  // 5. Texto Derecha (Blanco)
  doc.setTextColor(255, 255, 255);
  const xDerecha = 196;
  doc.setFontSize(16);
  doc.text('PICKING LIST', xDerecha, 18, { align: 'right' });
  doc.setFontSize(9);
  doc.text(`N°: ${orden.numero_orden}`, xDerecha, 26, { align: 'right' });
  doc.text(`Fecha: ${new Date(orden.fecha_despacho).toLocaleDateString()}`, xDerecha, 32, { align: 'right' });

  // Datos
  doc.setTextColor(51, 51, 51);
  doc.setFontSize(10);
  doc.text('CLIENTE:', 14, 55);
  doc.setFont('helvetica', 'bold');
  doc.text(orden.cliente_nombre || 'Cliente', 14, 61);
  doc.setFont('helvetica', 'normal');
  
  doc.text('REFERENCIA:', 130, 55);
  doc.text(orden.numero_cotizacion || '—', 130, 61);

  // Tabla
  const body = pickingList.map(item => [
    item.lotes?.productos?.nombre || 'Producto',
    item.lotes?.productos?.item_code || '—',
    item.lotes?.codigo_lote || '—',
    item.lotes?.fecha_vencimiento ? new Date(item.lotes.fecha_vencimiento).toLocaleDateString() : '—',
    item.cantidad_descontada
  ]);

  autoTable(doc, {
    startY: 70,
    head: [['Producto', 'Código', 'Lote', 'Vence', 'Cant.']],
    body: body,
    theme: 'grid',
    headStyles: { fillColor: colorNaranja, textColor: 255 },
    styles: { fontSize: 9 }
  });

  // Firmas
  const finalY = (doc as any).lastAutoTable.finalY + 30;
  doc.setFontSize(10);
  doc.setFont('helvetica', 'normal');
  
  doc.line(20, finalY, 80, finalY);
  doc.text('Entregado por Bodega', 30, finalY + 5);
  
  doc.line(130, finalY, 190, finalY);
  doc.text('Recibido por Cliente', 140, finalY + 5);

  doc.save(`PickingList_${orden.numero_orden}.pdf`);
}

// controllers/pdfController.ts

export function generarPdfInventario(inventario: any[], valorTotalBodega: number) {
  const doc = new jsPDF();
  
  // Colores
  const colorAzul: [number, number, number] = [2, 132, 199];
  const colorTexto: [number, number, number] = [51, 51, 51];

  // Cabecera
  doc.setFillColor(colorAzul[0], colorAzul[1], colorAzul[2]);
  doc.rect(0, 0, 210, 35, 'F');
  
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(18);
  doc.text('REPORTE DE INVENTARIO VALORIZADO', 14, 20);
  doc.setFontSize(10);
  doc.text('AgroLactec S.A. de C.V. - Control de Bodega', 14, 28);
  
  // Datos generales
  doc.setTextColor(colorTexto[0], colorTexto[1], colorTexto[2]);
  doc.setFontSize(10);
  doc.text(`Fecha de emisión: ${new Date().toLocaleString()}`, 14, 45);
  doc.setFont('helvetica', 'bold');
  doc.text(`Valor Total en Bodega: $${valorTotalBodega.toFixed(2)}`, 14, 52);
  doc.setFont('helvetica', 'normal');

  // Tabla
  const body = inventario.map(item => [
    item.productos?.nombre || 'Producto',
    item.codigo_lote,
    new Date(item.fecha_vencimiento).toLocaleDateString(),
    `${item.cajas_cerradas} cj`,
    `${item.unidades_sueltas} und`,
    `$${item.valor_total.toFixed(2)}`
  ]);

  autoTable(doc, {
    startY: 60,
    head: [['Producto', 'Lote', 'Vencimiento', 'Cajas Cerradas', 'Unid. Sueltas', 'Valor Total']],
    body: body,
    theme: 'grid',
    headStyles: { fillColor: colorAzul, textColor: 255 },
    styles: { fontSize: 9 }
  });

  // Firmas
  const finalY = (doc as any).lastAutoTable.finalY + 30;
  doc.line(20, finalY, 80, finalY);
  doc.text('Firma Gerente', 35, finalY + 5);
  doc.line(130, finalY, 190, finalY);
  doc.text('Firma Bodeguero', 145, finalY + 5);

  doc.save(`Inventario_Valorizado_${new Date().toISOString().split('T')[0]}.pdf`);
}

// ============================================================================
// 4. GENERAR PDF DE HISTORIAL DE COTIZACIONES
// ============================================================================
export function generarPdfHistorialCotizaciones(cotizaciones: any[]) {
  const doc = new jsPDF();
  const colorAzul: [number, number, number] = [2, 132, 199];

  doc.setFillColor(colorAzul[0], colorAzul[1], colorAzul[2]);
  doc.rect(0, 0, 210, 30, 'F');
  doc.setTextColor(255, 255, 255);
  doc.setFontSize(16);
  doc.text('HISTORIAL DE COTIZACIONES', 14, 20);

  doc.setTextColor(51, 51, 51);
  doc.setFontSize(10);
  doc.text(`Fecha de emisión: ${new Date().toLocaleString()}`, 14, 40);

  const body = cotizaciones.map(c => [
    c.numero_cotizacion,
    new Date(c.fecha_emision).toLocaleDateString(),
    c.cliente_nombre,
    `$${Number(c.total).toFixed(2)}`,
    c.estado
  ]);

  autoTable(doc, {
    startY: 45,
    head: [['N° Cotización', 'Fecha', 'Cliente', 'Total', 'Estado']],
    body: body,
    theme: 'grid',
    headStyles: { fillColor: colorAzul, textColor: 255 },
    styles: { fontSize: 9 }
  });

  doc.save(`Historial_Cotizaciones_${new Date().toISOString().split('T')[0]}.pdf`);
}

